// Non-model macOS diagnostic; reproduces the candidate bootstrap boundary and its composition failure.
import fs from 'node:fs/promises';import {existsSync} from 'node:fs';import os from 'node:os';import {resolve,join} from 'node:path';import {spawnSync} from 'node:child_process';import {bootstrapPolicy,buildRoleLaunch} from '../src/bootstrap.mjs';import {permissionArgs,hash} from '../src/launch.mjs';import {cleanEnv} from '../src/process.mjs';
const root=resolve('runtime/minimum-check'),job=join(root,'job'),peer=resolve('runtime/minimum-peer'),binary='/Applications/ChatGPT.app/Contents/Resources/codex-cli/CodexCLI.app/Contents/MacOS/codex';
await fs.mkdir(job,{recursive:true});await fs.mkdir(peer,{recursive:true});await fs.writeFile(join(job,'allowed.txt'),'SYNTHETIC_ALLOWED');await fs.writeFile(join(peer,'forbidden.txt'),'SYNTHETIC_PEER');
const profile=join(root,'bootstrap.sb');await fs.writeFile(profile,bootstrapPolicy(root));
const checks=[];const check=(name,cmd,args,ok)=>{const r=spawnSync(cmd,args,{cwd:job,env:cleanEnv(),encoding:'utf8',timeout:10000,maxBuffer:2**20});const passed=ok(r);checks.push({name,exit:r.status,passed,stdout:r.stdout,stderr:r.stderr});if(!passed)throw Error('MINIMUM_ISOLATION_FAILED:'+name);};
check('parent reads own synthetic data','/usr/bin/sandbox-exec',['-f',profile,'/bin/cat',join(job,'allowed.txt')],r=>r.status===0&&r.stdout==='SYNTHETIC_ALLOWED');
check('parent denies peer synthetic data','/usr/bin/sandbox-exec',['-f',profile,'/bin/cat',join(peer,'forbidden.txt')],r=>r.status!==0&&!r.stdout);
// Test openability only; never read or print credential or personal instruction bytes.
for(const [name,path,expect] of [['personal AGENTS',join(os.homedir(),'.codex','AGENTS.md'),false],['user config',join(os.homedir(),'.codex','config.toml'),false],['existing auth',join(os.homedir(),'.codex','auth.json'),true]]){
 if(!existsSync(path)){checks.push({name,present:false,passed:!expect});if(expect)throw Error('AUTH_NOT_PRESENT');continue;}
 check('parent open '+name,'/usr/bin/sandbox-exec',['-f',profile,'/bin/sh','-c','if [ -r "$1" ]; then echo READABLE; else echo DENIED; fi','probe',path],r=>r.status===0&&r.stdout.trim()===(expect?'READABLE':'DENIED'));
}
const native=['sandbox',...permissionArgs(job),'-P','probe','-C',job,'--'];
check('inner profile reads own synthetic data',binary,[...native,'/bin/cat',join(job,'allowed.txt')],r=>r.status===0&&r.stdout==='SYNTHETIC_ALLOWED');
check('inner profile denies peer synthetic data',binary,[...native,'/bin/cat',join(peer,'forbidden.txt')],r=>r.status!==0&&!r.stdout);
check('inner profile denies auth open',binary,[...native,'/bin/sh','-c','if [ -r "$1" ]; then echo READABLE; else echo DENIED; fi','probe',join(os.homedir(),'.codex','auth.json')],r=>r.status===0&&r.stdout.trim()==='DENIED');
const launch=buildRoleLaunch({binary,runtimeRoot:root,bootstrapFile:profile,jobDir:job,outputFile:join(root,'final.json'),schemaFile:join(root,'schema.json'),instructions:'Synthetic controlled role',model:'gpt-6-astra',effort:'low'});
const result={at:new Date().toISOString(),passed:true,checks,launch:launch.descriptor,launchFingerprint:launch.fingerprint,policy:bootstrapPolicy(root),parentReadScope:'auth file and own per-role runtime only within /Users; system runtime allowed',existingLoginUnchanged:true,realModelCallsAdded:0,globalConfigChanges:0,limitation:'Scoped synthetic launch checks only. Not full B03/B04 or multi-tenant isolation. debug prompt-input cannot use ignore-user-config and fails under parent deny; no equivalent prompt-dump claim.'};const composed=spawnSync('/usr/bin/sandbox-exec',['-f',profile,'/usr/bin/sandbox-exec','-p','(version 1)(allow default)','/bin/cat',join(job,'allowed.txt')],{cwd:job,env:cleanEnv(),encoding:'utf8',timeout:10000});
result.individualChecksPassed=result.passed;delete result.passed;result.composedSandbox={exit:composed.status,stdout:composed.stdout,stderr:composed.stderr,passed:composed.status===0&&composed.stdout==='SYNTHETIC_ALLOWED'};result.minimumReady=result.individualChecksPassed&&result.composedSandbox.passed;
await fs.mkdir('runtime',{recursive:true});await fs.writeFile('runtime/minimum-isolation-result.json',JSON.stringify(result,null,2));console.log(JSON.stringify({individualChecksPassed:result.individualChecksPassed,composedSandbox:result.composedSandbox,minimumReady:result.minimumReady,realModelCalls:0}));process.exitCode=result.minimumReady?0:2;
